// rules.yaml (11 P4-08; DEC-83): the research text behind each rule ref, one entry per numbered
// section of the research documents. Generated by `sim rules <package-dir>`, never edited by hand.
import { z } from "zod";
import { elementList, text } from "./common.ts";

export const rulesSchema = elementList(
  z.strictObject({
    /** Research cite as logged, for example `06 s3.2`. */
    id: z.string().regex(/^\d{2} s\d+(\.\d+)*$/, "Use NN sX.Y"),
    file: text,
    heading: text,
    /** Text under the heading, up to the next heading. May be empty. */
    text: z.string(),
    /** Titles of the sections directly below, for example `3.2 Cross-Border`. */
    subsections: z.array(text),
  }),
);
